import { preview } from 'vite'
import { spawn } from 'node:child_process'
import { mkdtemp } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { join } from 'node:path'
import assert from 'node:assert/strict'

const server = await preview({ preview: { host: '127.0.0.1', port: 0 } })
const url = server.resolvedUrls.local[0]
const profile = await mkdtemp(join(tmpdir(), 'find-a-park-layout-'))
const chrome = spawn(join(process.env.ProgramFiles, 'Google/Chrome/Application/chrome.exe'), [
  '--headless', '--disable-gpu', '--disable-extensions', '--no-first-run', '--remote-debugging-pipe',
  '--user-data-dir=' + profile, 'about:blank',
], { stdio: ['ignore','ignore','ignore','pipe','pipe'], windowsHide: true })
const pending = new Map()
let nextId = 0, buffer = ''
chrome.stdio[4].setEncoding('utf8')
chrome.stdio[4].on('data', chunk => {
  const messages = (buffer + chunk).split('\\0')
  buffer = messages.pop()
  for (const message of messages) {
    const { id, result, error } = JSON.parse(message)
    if (pending.has(id)) {
      const { resolve, reject } = pending.get(id)
      pending.delete(id)
      error ? reject(Error(error.message)) : resolve(result)
    }
  }
})
function send(method, params = {}, sessionId) {
  const id = ++nextId
  return new Promise((resolve, reject) => {
    pending.set(id, { resolve, reject })
    chrome.stdio[3].write(JSON.stringify({ id, method, params, sessionId }) + '\\0')
  })
}
const timeout = setTimeout(() => { chrome.kill(); process.exit(1) }, 20000)
try {
  const { targetId } = await send('Target.createTarget', { url: 'about:blank' })
  const { sessionId } = await send('Target.attachToTarget', { targetId, flatten: true })
  const page = (method, params) => send(method, params, sessionId)
  await page('Page.navigate', { url })
  for (const width of [1280, 375]) {
    await page('Emulation.setDeviceMetricsOverride', { width, height: 800, deviceScaleFactor: 1, mobile: false })
    const { result } = await page('Runtime.evaluate', { awaitPromise: true, returnByValue: true, expression: "'`(async () => {
      while (!document.querySelector('"'.map-panel')) await new Promise(resolve => setTimeout(resolve, 20))
      const side = document.querySelector('.park-sidebar').getBoundingClientRect()
      const map = document.querySelector('.map-panel').getBoundingClientRect()
      return { sideBySide: map.left >= side.right, stacked: map.top >= side.bottom, overflow: document.documentElement.scrollWidth > innerWidth }
    })()"'` })
    assert.deepEqual(result.value, { sideBySide: width === 1280, stacked: width === 375, overflow: false })
    console.log(width, result.value)
  }
} finally {
  await send('"'Browser.close')
  await server.close()
  clearTimeout(timeout)
}
